def prose_spacing(text):
    words='Algorithm|Initial|Lean|Lemma|Theorem|The|At|all|and|at|checked|closes|code|contributes|free|give|gives|is|level|margin|most|not|pp|score|side|window|as|by|every|from|lines|values'
    return re.sub(r'\b('+words+r')(\d+)(?![A-Za-z0-9_])',r'\1 \2',text)

